```js
// app.js
/* eslint-disable  no-console */
const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const morgan    = require('morgan');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

// ------------------------------------------------------------------
// Configuration
// ------------------------------------------------------------------
const app = express();
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

// ------------------------------------------------------------------
// Middleware stack
// ------------------------------------------------------------------
app.use(helmet());                                 // Security headers
app.use(cors({ origin: process.env.CORS_ORIGIN })); // CORS whitelist
app.use(rateLimit({                                 // Simple rate limiting
  windowMs: 15 * 60 * 1000,                       // 15 min
  max: 200,                                        // 200 req per window per IP
  standardHeaders: true,
  legacyHeaders: false
}));
app.use(express.json());                           // Parse JSON bodies
app.use(morgan('combined'));                       // HTTP request logging

// ------------------------------------------------------------------
// Routes
// ------------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example of a route that could receive user input.
// Even though we currently just return static users, the validation
// skeleton is ready for future extensions.
app.get(
  '/users',
  // --- optional query params ------------------------------------
  query('id')
    .optional()
    .isInt({ gt: 0 })
    .withMessage('user id must be a positive integer'),

  async (req, res, next) => {
    try {
      // Validate query params:
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        // 400 Bad Request – user mistakes
        return res.status(400).json({ errors: errors.array() });
      }

      // Business logic (future‑proofed)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' }
      ];

      // If a numeric id param is supplied, filter:
      const { id } = req.query;
      const result = id
        ? users.filter(u => u.id === Number(id))
        : users;

      res.json(result);
    } catch (err) {
      // Pass to global error handler
      next(err);
    }
  }
);

// ------------------------------------------------------------------
// 404 & global error handling
// ------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => {
  /* eslint-disable-next-line no-console */
  console.error(err);                                        // Log raw error
  const statusCode = err.statusCode || 500;
  const payload = {
    error: err.message || 'Internal Server Error'
  };

  // Hide stack traces in production
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    payload.stack = err.stack;
  }

  res.status(statusCode).json(payload);
});

// ------------------------------------------------------------------
// Start
// ------------------------------------------------------------------
app.listen(PORT, () => {
  /* eslint-disable-next-line no-console */
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What changed?

1. **Helmet** – adds a collection of HTTP response headers that mitigate several vulnerabilities: click‑jacking (`X-Frame-Options`), MIME sniffing, XSS (`X-XSS-Protection`), etc.

2. **CORS** – limits which origins can call your API. In production you’ll usually set `process.env.CORS_ORIGIN` to a whitelist.

3. **Rate‑limit** – reduces the risk of brute‑force or DoS attacks.

4. **Express JSON** – cleanses payload data and sends a clear `415` for unsupported media types. It also protects against malformed JSON that could crash the parser.

5. **Morgan** – structured, repeatable logging of inbound requests. Replace with a proper logging service if needed.

6. **Input validation** (express‑validator) – protects your future payloads from malformed data (e.g., SQL injections, XSS) and helps you send meaningful error codes before hitting core logic.

7. **Async error handling** – every `async` route uses a `try/catch`, and errors get forwarded to the single
   *global* error‑handler that returns a JSON error response and masks
   stack traces except in development.

8. **404 catcher** – prevents “no route found” leaks that might help an attacker craft new queries.

9. **Environmental port** – `{PORT}` is configurable; you’re not forced into `3000` in production.

10. **Production check** (`process.env.NODE_ENV`) – ensures you’re not leaking stack traces to end‑users.

