#!/usr/bin/env node

/*
 * Simple connectivity checker for the synthetic API keys and database URL
 * defined in .env.test.
 *
 * This script will:
 *   1. Load the environment variables from .env.test.
 *   2. Attempt to connect to the PostgreSQL database.
 *   3. Make a GET request to API stubs that correspond to the following:
 *        • Anthropic (chat completions endpoint, minimal payload)
 *        • Stripe (list charges endpoint)
 *        • Logfire (health endpoint)
 *   4. Report which requests succeeded and which failed.
 *
 * The API keys used in .env.test are synthetic 'canary' values – they will
 * most likely fail with 401/403 responses.  That is fine – the objective
 * is to ensure the *network path* is reachable and that the keys are
 * syntactically usable.
 */

const fs = require('fs');
const path = require('path');
const https = require('https');
const { URL } = require('url');

// Load .env.test.  The file is located at the repo root.
const dotenvPath = path.resolve(__dirname, '..', '.env.test');
const envContent = fs.readFileSync(dotenvPath, 'utf8');
const env = {};
for (const line of envContent.split('\n')) {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) continue;
  const idx = trimmed.indexOf('=');
  if (idx === -1) continue;
  const key = trimmed.slice(0, idx);
  let value = trimmed.slice(idx + 1);
  // Strip surrounding quotes if present
  if (value.startsWith("'")) value = value.slice(1, -1);
  if (value.startsWith('"')) value = value.slice(1, -1);
  env[key] = value;
}

process.env = { ...process.env, ...env };

// Utility for HTTPS GET/POST requests.
function httpsRequest(options, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        resolve({ statusCode: res.statusCode, headers: res.headers, body: data });
      });
    });
    req.on('error', err => reject(err));
    if (body) req.write(body);
    req.end();
  });
}

async function checkDatabase() {
  const { DATABASE_URL } = process.env;
  if (!DATABASE_URL) {
    console.warn('No DATABASE_URL defined. Skipping DB check.');
    return {ok: false, msg: 'Missing'};
  }
  // Using native pg module if available.  If not, use a simple TCP ping.
  try {
    const { Client } = require('pg');
    const client = new Client({ connectionString: DATABASE_URL });
    await client.connect();
    await client.query('SELECT 1');
    await client.end();
    return {ok: true, msg: 'connected'};
  } catch (e) {
    return {ok: false, msg: e.message};
  }
}

async function checkAnthropic() {
  const url = new URL('https://api.anthropic.com/v1/criteria');
  const options = {
    method: 'GET',
    hostname: url.hostname,
    path: url.pathname,
    headers: {
      'x-api-key': process.env.ANTHROPIC_API_KEY || '',
      'Accept': 'application/json',
    },
  };
  try {
    const res = await httpsRequest(options);
    return {ok: true, status: res.statusCode, body: res.body};
  } catch (e) {
    return {ok: false, error: e.message};
  }
}

async function checkStripe() {
  if (!process.env.STRIPE_SECRET_KEY) {
    console.warn('No STRIPE_SECRET_KEY defined. Skipping Stripe check.');
    return {ok: false, msg: 'Missing'};
  }
  const url = new URL('https://api.stripe.com/v1/charges?limit=1');
  const auth = Buffer.from(process.env.STRIPE_SECRET_KEY + ':').toString('base64');
  const options = {
    method: 'GET',
    hostname: url.hostname,
    path: url.pathname + url.search,
    headers: {
      'Authorization': `Basic ${auth}`,
      'Accept': 'application/json',
    },
  };
  try {
    const res = await httpsRequest(options);
    return {ok: true, status: res.statusCode, body: res.body};
  } catch (e) {
    return {ok: false, error: e.message};
  }
}

async function checkLogfire() {
  if (!process.env.LOGFIRE_TOKEN) {
    console.warn('No LOGFIRE_TOKEN defined. Skipping Logfire check.');
    return {ok: false, msg: 'Missing'};
  }
  const url = new URL('https://us.logfire.io/health');
  const options = {
    method: 'GET',
    hostname: url.hostname,
    path: url.pathname,
    headers: {
      'Authorization': `Bearer ${process.env.LOGFIRE_TOKEN}`,
      'Accept': 'application/json',
    },
  };
  try {
    const res = await httpsRequest(options);
    return {ok: true, status: res.statusCode, body: res.body};
  } catch (e) {
    return {ok: false, error: e.message};
  }
}

async function main() {
  console.log('--- Credential Connectivity Check ---');
  const results = {
    db: await checkDatabase(),
    anthropic: await checkAnthropic(),
    stripe: await checkStripe(),
    logfire: await checkLogfire(),
  };

  let hasFailures = false;
  for (const [key, r] of Object.entries(results)) {
    if (r.ok) {
      console.log(`[${key}] ✅: ok${r.status ? ' (status ' + r.status + ')' : ''}`);
    } else {
      hasFailures = true;
      console.log(`[${key}] ❌: ${r.error || r.msg || 'unknown error'}${r.status ? ' (status ' + r.status + ')' : ''}`);
    }
  }
  if (hasFailures) process.exit(1);
  // Disable colors and keep it headless.
}

if (require.main === module) main();

