  const resp = { error: 'Internal Server Error' };
  if (process.env.NODE_ENV === 'development') resp.details = err.message;
  res.status(err.status || 500).json(resp);
});

app.use(errors()); // celebrate validation errors

/* ------------ Server startup ------------- */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => logger.info(`Server listening on ${PORT}`));

/* ------------ Graceful shutdown ------------- */
