#!/usr/bin/env node

/**
 * Quick end‑to‑end connectivity test for the sensitive credentials that live in
 * .env.test.  Runs in isolation – no database tables are altered.
 *
 * If you want to add new secret types, just copy the pattern below:
 *
 *   // <Service name>
 *   try { … } catch (err) { … }
 *
 * Non‑fatal failures are reported but do not break the script (useful for
 * services that expose no public test endpoint).
 */

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const Stripe = require('stripe');
const axios = require('axios');

(async () => {
  // ------------------------------------------------------------------
  // 1. PostgreSQL – simple SELECT 1
  // ------------------------------------------------------------------
  try {
    const pgClient = new Client({ connectionString: process.env.DATABASE_URL });
    await pgClient.connect();
    const res = await pgClient.query('SELECT 1 AS result');
    if (res.rows[0].result !== 1) throw new Error('Unexpected DB result');
    await pgClient.end();

    console.log('✅  PostgreSQL connection ✔︎');
  } catch (err) {
    console.error('❌  PostgreSQL test FAILED:', err.message);
    process.exit(1);
  }

  // ------------------------------------------------------------------
  // 2. AWS STS – GetCallerIdentity
  // ------------------------------------------------------------------
  try {
    const sts = new STSClient({ region: 'us-east-1' });
    const command = new GetCallerIdentityCommand({});
    const output = await sts.send(command);

    if (!output.Arn) throw new Error('Missing Arn');
    console.log(`✅  AWS STS Identity ✔︎  (${output.Arn})`);
  } catch (err) {
    console.error('❌  AWS STS test FAILED:', err.message);
    process.exit(1);
  }

  // ------------------------------------------------------------------
  // 3. Anthropic – basic /messages call
  // ------------------------------------------------------------------
  try {
    const payload = JSON.stringify({
      model: 'claude-2',
      max_tokens_to_sample: 5,
      input: 'Hello world',
    });

    const { data, status } = await axios.post(
      'https://api.anthropic.com/v1/messages',
      payload,
      {
        headers: {
          Authorization: `Bearer ${process.env.ANTHROPIC_API_KEY}`,
          'Content-Type': 'application/json',
        },
        timeout: 10_000, // 10 s
      }
    );

    if (status < 200 || status >= 300) throw new Error(`HTTP ${status}`);
    console.log('✅  Anthropic API ✔︎  (status', status, ')');
  } catch (err) {
    console.error('❌  Anthropic test FAILED:', err.response?.data ?? err.message);
    process.exit(1);
  }

  // ------------------------------------------------------------------
  // 4. Stripe – list a customer
  // ------------------------------------------------------------------
  try {
    const stripe = Stripe(process.env.STRIPE_SECRET_KEY);
    const list = await stripe.customers.list({ limit: 1 });

    if (!Array.isArray(list.data)) throw new Error('Unexpected response');
    console.log(`✅  Stripe OK (found ${list.data.length} customer${list.data.length !== 1 ? 's' : ''})`);
  } catch (err) {
    console.error('❌  Stripe test FAILED:', err.message);
    process.exit(1);
  }

  // ------------------------------------------------------------------
  // 5. Logfire – optional ping (non‑fatal)
  // ------------------------------------------------------------------
  try {
    const payload = { event: { type: 'verify-credentials', data: { msg: 'test' } } };
    const { status } = await axios.post(
      'https://api.logfire.com/v1/track', // <-- might change in the future
      payload,
      { headers: { Authorization: `Token ${process.env.LOGFIRE_TOKEN}` } }
    );
    console.log(`✅  Logfire Ping ✔︎  (status ${status})`);
  } catch (err) {
    // Logfire may not expose a public test endpoint, so we don't fail here
    console.warn('⚠︎  Logfire test NOT RUNNABLE (ignored):', err.message);
  }

  console.log('\n🎉  All credential checks passed ✅');
})();
