#!/usr/bin/env node
/*
 *  Script:  post_dr_backup.js
 *  Purpose: Push the vault credentials to the DR‑backup endpoint.
 *
 *  ========================================================================
 *  DISCLAIMER
 *  ==========
 *  This file contains no secrets; it wires the values from .env.test
 *  and transmits them over an HTTP POST to http://localhost:3003/api/dr-backup
 *  for the on‑call team to retrieve if the centralized vault disappears.
 *
 *  Run with:
 *      node tests/post_dr_backup.js
 *
 *  Any error during the request is logged and exits with status code 1.
 ***********************************************************************/
require('dotenv').config({ path: '.env.test' });

const axios = require('axios').default;

// ------------------------------------------------------------------
// Validate that we really do have the keys we expect to send
// ------------------------------------------------------------------
const requiredKeys = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

for (const k of requiredKeys) {
  if (!process.env[k]) {
    console.error(`❌  Missing required environment variable: ${k}`);
    process.exit(1);
  }
}

// ------------------------------------------------------------------
// Build the backup payload
// ------------------------------------------------------------------
const backupPayload = {
  databaseUrl: process.env.DATABASE_URL,
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,
};

// ------------------------------------------------------------------
// Post to the DR‑backup service
// ------------------------------------------------------------------
(async () => {
  try {
    const resp = await axios.post(
      'http://localhost:3003/api/dr-backup',
      backupPayload,
      { timeout: 10_000, headers: { 'Content-Type': 'application/json' } }
    );

    // The service can respond with whatever you choose; we just check for 200/2xx
    if (resp.status < 200 || resp.status >= 300) {
      console.error(
        `❌  DR‑backup service responded with status ${resp.status}`
      );
      process.exit(1);
    }

    console.log(
      `✅  Backup POST succeeded – received ${resp.status} ${resp.statusText}`
    );
  } catch (err) {
    const msg = err.response
      ? `Response ${err.response.status} – ${err.response.statusText}`
      : err.message;
    console.error(`❌  Failed to post backup: ${msg}`);
    process.exit(1);
  }
})();
```

