const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();

/* ------------------------------------------------------------------
 * 1. Security & common middleware
 * ------------------------------------------------------------------ */
app.use(helmet());                               // Set secure HTTP headers
app.use(cors({ origin: 'https://mytrusteddomain.com' })); // Restrict CORS
app.use(bodyParser.json());                      // Parse JSON bodies
app.use(bodyParser.urlencoded({ extended: false })); // Parse URL‑encoded

/* ------------------------------------------------------------------
 * 2. Rate limiting (adjust options for your traffic patterns)
 * ------------------------------------------------------------------ */
