app.use(helmet());      // Sets defensive HTTP headers
app.use(cors({        // Tailor this whitelist to your needs
  origin: ['https://example.com'],
}));
app.use(json());       // Parse JSON bodies for POST/PUT

/* ---------- 2️⃣ Rate limiting ---------- */
