      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (e) {
    next(e); // forward to global error handler
  }
});

/* ---------- 4️⃣ 404 handler ---------- */
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

/* ---------- 5️⃣ Global error handler ---------- */
app.use((err, req, res, next) => {
