#!/usr/bin/env node

/*
  Proof‑of‑concept script to verify that the "canary" credentials defined in
  .env.test are still considered valid by the services they target.

  It will:
  • Connect to PostgreSQL using DATABASE_URL.
  • Ask the Anthropic API for a list of available models.
  • Call Stripes to list customers (the cheapest call).
  • List S3 buckets with the supplied AWS credentials.

  All operations are wrapped in `try/catch` blocks and any non‑200 HTTP
  responses or connection errors are reported to the console.

  Run with:
    node check-secrets.test.js

  Dependencies:
    npm install pg axios aws-sdk @anthropic-ai/sdk stripe dotenv
*/

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const axios = require('axios');
const aws = require('aws-sdk');
const { Anthropic } = require('@anthropic-ai/sdk');
const Stripe = require('stripe');

async function testPostgres() {
  console.log('\n\n[PostgreSQL]');
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  try {
    await client.connect();
    const res = await client.query('SELECT 1 + 1 AS result');
    console.log('  ✔ Connected. Result:', res.rows[0].result);
  } catch (err) {
    console.error('  ✗ Connection failed:', err.message);
  } finally {
    await client.end();
  }
}

async function testAnthropic() {
  console.log('\n[Anthropic]');
  const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
  try {
    const res = await client.request({
      prompt: 'List available models',
      model: 'claude-3-5-sonnet-20240620', // Example; remove if not needed
      temperature: 0,
    });
    console.log('  ✔ API responded with:', res.completion.slice(0, 60), '…');
  } catch (err) {
    console.error('  ✗ API call failed:', err.message || err.response?.data || err.stack);
  }
}

async function testStripe() {
  console.log('\n[Stripe]');
  const stripe = Stripe(process.env.STRIPE_SECRET_KEY);
  try {
    const customers = await stripe.customers.list({ limit: 1 });
    console.log('  ✔ Customers list fetched. Count:', customers.data.length);
  } catch (err) {
    console.error('  ✗ Stripe API error:', err.message || err.code, err);
  }
}

async function testAWS() {
  console.log('\n[AWS S3]');
  const s3 = new aws.S3({
    region: 'us-east-1', // adjust if needed
    credentials: {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    },
  });
  try {
    const data = await s3.listBuckets().promise();
    console.log('  ✔ Buckets:', data.Buckets.map(b => b.Name).join(', '));
  } catch (err) {
    console.error('  ✗ List buckets failed:', err.message);
  }
}

async function main() {
  await testPostgres();
  await testAnthropic();
  await testStripe();
  await testAWS();
}

main().catch(err => {
  console.error('Unexpected error:', err);
  process.exit(1);
});

#!/usr/bin/env node

/*
  Disaster‑Recovery backup script.
  It reads the credentials from .env.test, serialises them to JSON, and
  POSTs that JSON to http://localhost:3003/api/dr-backup.

  This is a *transitional* help tool – you should store the backup in a
  separate, protected vault rather than keeping a plain‑text copy.

  Run with:
    node dr-backup.js

  Dependencies:
    npm i --save-dev axios dotenv
*/

require('dotenv').config({ path: '.env.test' });
const axios = require('axios');

const backupData = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

(async () => {
  try {
    const res = await axios.post('http://localhost:3003/api/dr-backup', backupData, {
      headers: { 'Content-Type': 'application/json' },
    });
    console.log('Backup succeeded:', res.status, res.statusText);
  } catch (err) {
    console.error('Backup failed:', err.message);
    process.exit(1);
  }
})();

