## 1. Prepare a test script

Create a file, e.g. `scripts/validate-secrets.js` (or place it in a new folder `tests`).

```js
#!/usr/bin/env node
/**
 * Validate the synthetic secrets present in .env.test.
 *
 * NB: This script must be *run locally* or in your own CI environment—
 * it deliberately attempts network connections so that you can be sure
 * the values you think are “CANARY” actually work (or don’t).
 */

const fs   = require('fs');
const path = require('path');
const dotenv = require('dotenv');
const { Client } = require('pg');
const fetch  = require('node-fetch');      // npm install node-fetch@2

// --- Load the synthetic credentials ---------------------------------------
const envPath = path.resolve(process.cwd(), '.env.test');
if (!fs.existsSync(envPath)) {
  console.error('❌  .env.test not found in the repo root.');
  process.exit(1);
}
dotenv.config({ path: envPath });
const { DATABASE_URL, ANTHROPIC_API_KEY } = process.env;

// --- Helper ---------------------------------------------------------------
const log = msg => console.log(`> ${msg}`);

// --- 1️⃣  Test database connection -----------------------------------------
async function testDB() {
  if (!DATABASE_URL) {
    console.warn('⚠️  No DATABASE_URL set, skipping DB test.');
    return;
  }

  log(`Connecting to PostgreSQL via ${DATABASE_URL}`);
  const client = new Client({ connectionString: DATABASE_URL });

  try {
    await client.connect();
    const { rows } = await client.query('SELECT 1 + 1 AS result');
    console.log('✅  Database returned:', rows[0].result); // should be 2
  } catch (err) {
    console.error('❌  Database test failed.');
    console.error(err.message);
  } finally {
    await client.end();
  }
}

// --- 2️⃣  Test Anthropic API key ------------------------------------------
async function testAnthropic() {
  if (!ANTHROPIC_API_KEY) {
    console.warn('⚠️  No ANTHROPIC_API_KEY set, skipping Anthropic test.');
    return;
  }

  log('Calling Anthropic “/completions” endpoint with a sanity‑check prompt.');

  const url = 'https://api.anthropic.com/v1/completions';
  const payload = {
    model: 'claude-3-haiku-20240307',
    prompt: "Say hello",
    max_tokens_to_sample: 5
  };

  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': ANTHROPIC_API_KEY
      },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      throw new Error(`HTTP ${res.status} – ${await res.text()}`);
    }

    const data = await res.json();
    console.log('✅  Anthropic responded with:', data.completion.trim());
  } catch (err) {
    console.error('❌  Anthropic API test failed.');
    console.error(err.message);
  }
}

// --------------------------------------------------------------------------
async function run() {
  await testDB();
  await testAnthropic();
}

run().catch(err => {
  console.error('❌  Unexpected failure:', err);
  process.exit(1);
});
```

### How to run it

```bash
# 1. Install the small deps
npm install pg node-fetch@2 dotenv

# 2. Run the script
node scripts/validate-secrets.js
```

You’ll see either “✅” messages confirming a connection or a descriptive error telling you that, e.g., the database rejects the credentials, the host is unreachable, or the API key is rejected by Anthropic.

